import sys
import math

MOD = 1_000_000_007

def factorize(x):
    factors = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            factors[d] = factors.get(d, 0) + 1
            x //= d
        d += 1 if d == 2 else 2
    if x > 1:
        factors[x] = factors.get(x, 0) + 1
    return factors

def nCr(n, r, fact, inv_fact):
    if r < 0 or r > n:
        return 0
    return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    # Factorize m
    total_factors = {}
    for num in arr:
        fac = factorize(num)
        for p, exp in fac.items():
            total_factors[p] = total_factors.get(p, 0) + exp

    # Precompute factorials up to max needed
    max_exp = sum(total_factors.values())
    max_n = n + max_exp  # safe upper bound for factorials
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i-1] * i % MOD

    inv_fact = [1] * (max_n + 1)
    inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
    for i in range(max_n-1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    # For each prime factor, count ways to distribute exponents into n slots
    ans = 1
    for exp in total_factors.values():
        ways = nCr(exp + n - 1, n - 1, fact, inv_fact)
        ans = ans * ways % MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()

