import sys
import math

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))

    # If there's already a 1, answer is n - (number of ones)
    ones = a.count(1)
    if ones > 0:
        print(n - ones)
        return

    # Find shortest subarray with gcd = 1
    min_len = float('inf')
    for i in range(n):
        g = a[i]
        for j in range(i, n):
            g = math.gcd(g, a[j])
            if g == 1:
                min_len = min(min_len, j - i + 1)
                break

    if min_len == float('inf'):
        print(-1)
    else:
        # We need (min_len - 1) ops to create a 1 in that subarray,
        # then n - 1 ops to spread it to the rest
        print((min_len - 1) + (n - 1))

if __name__ == "__main__":
    solve()

