from collections import deque

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    a = [0] + [int(next(it)) for _ in range(n)]  # 1‑based indexing

    # Read edges (good pairs)
    adj = [[] for _ in range(n + 1)]
    edges = []
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        edges.append((u, v))
        adj[u].append(v)
        adj[v].append(u)

    # Bipartite coloring (since i + j odd => different parity)
    color = [-1] * (n + 1)
    bipartite = True
    for start in range(1, n + 1):
        if color[start] == -1:
            q = deque([start])
            color[start] = 0
            while q:
                u = q.popleft()
                for w in adj[u]:
                    if color[w] == -1:
                        color[w] = color[u] ^ 1
                        q.append(w)
                    elif color[w] == color[u]:
                        bipartite = False

    if not bipartite:
        print(0)
        return

    # Build flow network: source s = 0, sink t = 1, then left nodes 2..n+1, right nodes n+2..2n+1
    # But n ≤ 100, so we can map directly
    # left side: color 0, right side: color 1
    left_nodes = [i for i in range(1, n + 1) if color[i] == 0]
    right_nodes = [i for i in range(1, n + 1) if color[i] == 1]
    left_id = {node: idx + 2 for idx, node in enumerate(left_nodes)}
    right_id = {node: idx + 2 + len(left_nodes) for idx, node in enumerate(right_nodes)}
    node_count = 2 + len(left_nodes) + len(right_nodes)
    s = 0
    t = 1

    # For each prime factor, build a separate flow network
    # First, factorize all a[i]
    primes = set()
    def factorize(x):
        factors = {}
        d = 2
        while d * d <= x:
            while x % d == 0:
                factors[d] = factors.get(d, 0) + 1
                x //= d
            d += 1 if d == 2 else 2  # skip even numbers after 2
        if x > 1:
            factors[x] = factors.get(x, 0) + 1
        return factors

    factor_counts = [None] * (n + 1)
    for i in range(1, n + 1):
        factor_counts[i] = factorize(a[i])
        primes.update(factor_counts[i].keys())

    total_flow = 0
    for prime in primes:
        # Build capacity for this prime
        cap = [[0] * node_count for _ in range(node_count)]
        for u in left_nodes:
            uid = left_id[u]
            cnt = factor_counts[u].get(prime, 0)
            cap[s][uid] = cnt
        for u in right_nodes:
            uid = right_id[u]
            cnt = factor_counts[u].get(prime, 0)
            cap[uid][t] = cnt
        for u, v in edges:
            # We stored edges as undirected, but flow is directed from left to right
            if color[u] == 0:
                left = u
                right = v
            else:
                left = v
                right = u
            lid = left_id[left]
            rid = right_id[right]
            cap[lid][rid] = float('inf')

        # Dinic's max flow
        def max_flow(capacity):
            n_nodes = len(capacity)
            adj_flow = [[] for _ in range(n_nodes)]
            for i in range(n_nodes):
                for j in range(n_nodes):
                    if capacity[i][j] > 0 or capacity[j][i] > 0:
                        adj_flow[i].append(j)
            flow = [[0] * n_nodes for _ in range(n_nodes)]

            def bfs():
                level = [-1] * n_nodes
                level[s] = 0
                q = deque([s])
                while q:
                    u = q.popleft()
                    for v in adj_flow[u]:
                        if level[v] == -1 and flow[u][v] < capacity[u][v]:
                            level[v] = level[u] + 1
                            q.append(v)
                return level

            def dfs(u, pushed, level):
                if u == t:
                    return pushed
                for idx in range(iter_ptr[u], len(adj_flow[u])):
                    v = adj_flow[u][idx]
                    if level[v] == level[u] + 1 and flow[u][v] < capacity[u][v]:
                        tr = dfs(v, min(pushed, capacity[u][v] - flow[u][v]), level)
                        if tr > 0:
                            flow[u][v] += tr
                            flow[v][u] -= tr
                            return tr
                    iter_ptr[u] += 1
                return 0

            f = 0
            while True:
                level = bfs()
                if level[t] == -1:
                    break
                iter_ptr = [0] * n_nodes
                while True:
                    pushed = dfs(s, float('inf'), level)
                    if pushed == 0:
                        break
                    f += pushed
            return f

        total_flow += max_flow(cap)

